//! A separately linked language module. Loom never links this crate at runtime.
#![allow(linker_messages)]

#[unsafe(no_mangle)]
pub extern "C" fn loom_tree_sitter_typescript() -> *const () {
    // SAFETY: the function is generated by Tree-sitter and returns its static grammar.
    unsafe { tree_sitter_typescript::LANGUAGE_TYPESCRIPT.into_raw()() }
}

#[unsafe(no_mangle)]
pub extern "C" fn loom_tree_sitter_tsx() -> *const () {
    // SAFETY: the function is generated by Tree-sitter and returns its static grammar.
    unsafe { tree_sitter_typescript::LANGUAGE_TSX.into_raw()() }
}
